<?php
namespace Modules\Inventory\Models;
use Illuminate\Database\Eloquent\Model;
class InventoryTransfer extends Model { protected $table='inventory_transfers'; protected $fillable=['asset_id','material_id','warehouse_id','from_classroom_id','to_classroom_id','type','quantity','status','printed_at','requested_by','decided_by','reason','decision_note','decision_number','decided_at','performed_at','performing_unit','using_unit','decision_date','signer','requesting_unit','supplemental_reason','general_note']; protected $casts=['quantity'=>'integer','printed_at'=>'datetime','decided_at'=>'datetime','performed_at'=>'date','decision_date'=>'date']; public function getQuantityAttribute($value){if((int)$value>0)return (int)$value;if(preg_match('/Số lượng chuyển:\s*(\d+)/u',(string)($this->attributes['general_note']??''),$match))return (int)$match[1];return 1;} public function getIsPrintedAttribute(){return !empty($this->attributes['printed_at'])||str_contains((string)($this->attributes['general_note']??''),'[ĐÃ IN QUYẾT ĐỊNH]');} public function asset(){return $this->belongsTo(InventoryAsset::class,'asset_id');} public function material(){return $this->belongsTo(InventoryMaterial::class,'material_id');} public function warehouse(){return $this->belongsTo(InventoryWarehouse::class,'warehouse_id');} public function fromClassroom(){return $this->belongsTo(\Modules\Classroom\Models\Classroom::class,'from_classroom_id');} public function toClassroom(){return $this->belongsTo(\Modules\Classroom\Models\Classroom::class,'to_classroom_id');} public function decidedBy(){return $this->belongsTo(\App\Models\User::class,'decided_by');} }
